css:
.heading { font-size: 2em; color: #000; font-weight: bold; margin-bottom: .5em; }
.parahead { font-size: 1.2em; color: #000; font-weight: bold; margin-bottom: .3em; }
.textbold { font-size: .9em; color: #000; font-weight: bold; }
.textnormal { font-size: .9em; color: #000; font-weight: normal; }
.textsmall { color: #000; font-size: .80em; }

/* landscape/portrait guard: frappe's print_format.css sets a body min-height
   under @media screen, which wkhtmltopdf uses, and that grows a blank page */
body { min-height: 0 !important; margin: 0 auto !important; }

.desc { white-space: pre-line; }
img { vertical-align: top; max-width: 100%; }
.vmg-lh img, .letter-head img { max-height: 22mm; width: auto; }
.vmg-lhf img, .letter-head-footer img { max-height: 14mm; width: auto; }
.print-format > div:last-child, .print-format p:last-child { margin-bottom: 0 !important; }

.vmg-f04 { font-size: 10pt; line-height: 1.05; zoom: .78; }

/* the print style ships `.print-format td, th { padding: 10px !important }`,
   which is what made every row tall. Every padding below therefore needs
   !important of its own to win. */
.vmg-f04 table td, .vmg-f04 table th { padding: 0 !important; }

/* the reference draws one crisp black frame around each block */
.vmg-f04 table.box { border: 1px solid #000; border-collapse: collapse; width: 100%; }
.vmg-f04 table.box > tbody > tr > td { border: 1px solid #000; }
.vmg-f04 table.plain { border: none; border-collapse: collapse; width: 100%; }
.vmg-f04 table.plain td { border: none; }

.vmg-f04 .doctitle { font-size: 1.5em; font-weight: bold; text-align: center;
  padding: 2px 0 7px 0 !important; }
.vmg-f04 .formcode { font-weight: bold; text-align: right; }

/* header box: two halves split by the reference's dotted rule */
.vmg-f04 table.hdr { table-layout: fixed; }
.vmg-f04 .hdr > tbody > tr > td { vertical-align: top !important; padding: 3px 6px !important; }
.vmg-f04 .hdr .kv { table-layout: fixed; }
.vmg-f04 .hdr .half-left { border: none !important; border-right: 1px dotted #000 !important; }
.vmg-f04 .hdr .half-right { border: none !important; }
.vmg-f04 .kv td { border: none; padding: 0 !important; vertical-align: top !important;
  line-height: 1.25; }
.vmg-f04 .kv .k { font-weight: bold; white-space: nowrap; width: 34%; }
.vmg-f04 .kv .c { width: 5%; }
.vmg-f04 .kv .v { word-wrap: break-word; }

/* items */
.vmg-f04 table.items { border: 1px solid #000; border-collapse: collapse; width: 100%;
  table-layout: fixed; }
.vmg-f04 table.items th { border: 1px solid #000; font-weight: bold; text-align: center;
  padding: 2px 5px !important; color: #000; background-color: #d9d9d9;
  -webkit-print-color-adjust: exact; print-color-adjust: exact; }
.vmg-f04 table.items td { border: 1px dotted #000; padding: 2px 5px !important;
  vertical-align: top !important; }

.vmg-f04 .totals td { border: none; padding: 0 1px !important; }
.vmg-f04 .totline { font-weight: bold; text-align: right; }
.vmg-f04 .totval { text-align: right; }

.vmg-f04 .box td { padding: 3px 6px !important; }

.vmg-f04 .terms ol { margin: 1px 0 0 0; padding-left: 16px; }
.vmg-f04 .terms li { margin-bottom: 1px; }
.vmg-f04 .terms p { margin: 0 0 1px 0; }
.vmg-f04 .desc { margin: 0; }
.vmg-f04 .flag { color: #b00000; font-weight: bold; }
